/*
# Seed Patriarchs — Batch 2 (Patriarchs 6-10)

Inserts 5 more Coptic Patriarchs with full biographical data.
*/

INSERT INTO patriarchs (id, name_ar, name_en, papal_number, birth_date, death_date, papacy_start, papacy_end, century, short_bio_ar, biography_ar, historical_background_ar, faith_defense_ar, challenges_ar, contributions_ar, image_url, image_source, image_credit)
VALUES
('a0000001-0000-0000-0000-000000000006',
 'البابا سيمان الثاني المعروف بالدباغ', 'Pope Simon II the Tanner', 51,
 'غير معروف', 'غير معروف', 'حوالي 990 م', 'حوالي 1020 م', 11,
 'البابا الحادي والخمسون، الذي صلّى فتحرّك جبل المقطم بمعجزة الإيمان في عهد الخليفة الفاطمي.',
 'يُعرف البابا سيمان الثاني بمعجزة تحريك جبل المقطم. في عهد الخليفة الفاطمي الحاكم بأمر الله، طُلب من المسيحيين أن يحققوا آية من إنجيلهم: "لو كان لكم إيمان مثل حبة الخردل فلوقلتم لهذا الجبل انتقل من هنا إلى هناك يننتقل". صام البابا سيمان والشعب القبطي ثلاثة أيام. ظهر له في رؤيا رجل فقير دباغ اسمه سمعان السرياني يقال إنه صاحب هذه المعجزة. في يوم الأحد، اجتمع البابا مع الأساقفة والشعب ومع الخليفة، وصلّوا فتحرّك الجبل. هذه المعجزة من أشهر المعجزات في تاريخ الكنيسة القبطية.',
 'كانت مصر تحت حكم الفاطميين الشيعة. الخليفة الحاكم بأمر الله كان يضطهد الأقباط ويفرض عليهم قيوداً شديدة. في تلك الفترة، كان المسيحيون يواجهون تحديات وضغوطاً لإثبات صحة إيمانهم.',
 'أثبت البابا سيمان بالمعجزة أن الإيمان الأرثوذكسي حيّ وفعّال. لم يلجأ إلى المقاومة السياسية بل إلى الصلاة والصوم. جمع الشعب كله في صلاة واحدة، مظهراً أن قوة الكنيسة في إيمانها ووحدتها لا في السلاح.',
 'ضغوط واضطهاد من الخليفة الحاكم بأمر الله. طلب معجزة مستحيلة من الإنجيل كاختبار للإيمان. خطر إبادة المسيحيين إذا فشلوا.',
 'معجزة تحريك جبل المقطم، جمع الشعب القبطي في صلاة موحدة، إحياء كنيسة القديس العذراء بجبل المقطم (كنيسة المعلاقة).',
 '', '', '')
ON CONFLICT (papal_number) DO NOTHING;

INSERT INTO patriarchs (id, name_ar, name_en, papal_number, birth_date, death_date, papacy_start, papacy_end, century, short_bio_ar, biography_ar, historical_background_ar, faith_defense_ar, challenges_ar, contributions_ar, image_url, image_source, image_credit)
VALUES
('a0000001-0000-0000-0000-000000000007',
 'البابا كيرلس الرابع أبو الإصلاح', 'Pope Cyril IV the Reformer', 110,
 '1816 م', '31 يناير 1861 م', '1854 م', '31 يناير 1861 م', 19,
 'البابا المئة والعاشر، الملقب بـ"أبو الإصلاح"، أعاد بناء الكنيسة القبطية حديثاً بالتعليم والمدارس والطباعة.',
 'وُلد داود (اسمه قبل البطريركية) في سهاج سنة 1816 م. ترهب في دير البراموس بـوادي النطرون. اختير بابا للإسكندرية سنة 1854 م. بدأ مشروع إصلاح شامل: أسس المدارس القبطية الأولى في القاهرة، أدخل التعليم الحديث في الكنيسة، أسس مطبعة قبطية لطبع الكتب الكنسية، أرسل بعثات دراسية إلى أوروبا. تنيّح فجأة في 31 يناير 1861 م.',
 'كانت مصر في القرن التاسع عشر تحت حكم محمد علي وخلفائه. كانت الكنيسة القبطية في حالة ضعف وجهل بعد قرون من الاضطهاد والإهمال. لم يكن هناك تعليم حديث للأقباط.',
 'أدرك كيرلس الرابع أن الحفاظ على الإيمان لا يكون بالدفاع العقائدي فقط، بل بالتعليم والوعي. أسس المدارس لتعليم الأقباط دينهم وثقافتهم. بطباعة الكتب الكنسية، جعل الإيمان متاحاً للجميع.',
 'مقاومة شديدة من بعض الأساقفة والكهنة الذين لم يوافقوا على إصلاحاته. صعوبات مالية لمشاريعه الكبيرة. فترة خدمته القصيرة (7 سنوات فقط).',
 'تأسيس المدارس القبطية الأولى، إدخال التعليم الحديث في الكنيسة، تأسيس المطبعة القبطية، إرسال البعثات الدراسية إلى أوروبا.',
 '', '', '')
ON CONFLICT (papal_number) DO NOTHING;

INSERT INTO patriarchs (id, name_ar, name_en, papal_number, birth_date, death_date, papacy_start, papacy_end, century, short_bio_ar, biography_ar, historical_background_ar, faith_defense_ar, challenges_ar, contributions_ar, image_url, image_source, image_credit)
VALUES
('a0000001-0000-0000-0000-000000000008',
 'البابا كيرلس السادس', 'Pope Cyril VI', 116,
 '8 أغسطس 1902 م', '9 مارس 1971 م', '10 مايو 1959 م', '9 مارس 1971 م', 20,
 'البابا المئة والسادس عشر، الذي نقل الكنيسة القبطية إلى عصر جديد بنقل مقر البابوية إلى الدير وبظهور العذراء بكنيسة الزيتون.',
 'وُلد عازر يوسف عطا في طندتا بمحافظة الغربية في 8 أغسطس 1902 م. ترهب في دير البراموس باسم مينا المتوحد سنة 1928 م. اختير بابا للإسكندرية في 10 مايو 1959 م. في عهده، حدثت ظهورات العذراء مريم في كنيسة العذراء بالزيتون بالقاهرة من 2 أبريل 1968 م إلى 1971 م. نقل مقر البابوية إلى دير الأنبا بيشوي بوادي النطرون. استقبل رفات القديس مرقس من البابا بولس السادس سنة 1968 م. تنيّح في 9 مارس 1971 م.',
 'كانت فترة الستينيات فترة تغييرات كبيرة في مصر والشرق الأوسط. كانت الكنيسة القبطية في حاجة إلى نهضة روحية ورعوية. كانت الأديرة في حالة ضعف، والرهبنة شبه مندثرة.',
 'حفظ كيرلس السادس الإيمان بإحياء الرهبنة القبطية التي كانت على وشك الانقراض. بنقله مقر البابوية إلى الدير، أعاد الارتباط بين البطريركية والرهبنة. بظهورات العذراء في الزيتون، أعطى الشعب القبطي علامة روحية قوية.',
 'صعوبة إحياء الرهبنة في أديرة مهجورة. معارضة بعض الأساقفة لنقل مقر البابوية. ضغوط سياسية واجتماعية في عهد ناصر.',
 'نقل مقر البابوية إلى وادي النطرون، إحياء الرهبنة القبطية، ظهورات العذراء بالزيتون (1968-1971)، استقبال رفات القديس مرقس (1968).',
 '', '', '')
ON CONFLICT (papal_number) DO NOTHING;

INSERT INTO patriarchs (id, name_ar, name_en, papal_number, birth_date, death_date, papacy_start, papacy_end, century, short_bio_ar, biography_ar, historical_background_ar, faith_defense_ar, challenges_ar, contributions_ar, image_url, image_source, image_credit)
VALUES
('a0000001-0000-0000-0000-000000000009',
 'البابا شنودة الثالث', 'Pope Shenouda III', 117,
 '3 أغسطس 1923 م', '17 مارس 2012 م', '14 نوفمبر 1971 م', '17 مارس 2012 م', 20,
 'البابا المئة والسابع عشر، الذي نشر الكنيسة القبطية في العالم ووسّعها إلى أكثر من مئة دولة، ومعلّم جيل كامل.',
 'وُلد نظير جيد روفائيل في أسيوط في 3 أغسطس 1923 م. تخرّج من جامعة القاهرة بدرجة في التاريخ. ترهب في دير السريان باسم أنطونيوس السرياني سنة 1954 م. عُيّن أسقفاً للتعليم الديني سنة 1962 م. اختير بابا للإسكندرية في 14 نوفمبر 1971 م. انتشرت الكنيسة القبطية في أكثر من مئة دولة. اهتم بالتعليم الديني بشكل استثنائي. وقّع إعلان إيمان مشترك مع البابا كاثوليك روما سنة 1973 م. تنيّح في 17 مارس 2012 م بعد خدمة استمرت 40 سنة.',
 'كانت النصف الثاني من القرن العشرين فترة هجرة واسعة للأقباط إلى الخارج. كانت الكنيسة القبطية بحاجة إلى قيادة تواكب هذا الانتشار.',
 'حفظ شنودة الثالث الإيمان بتعليمه المستمر. كان معلّماً جيل كامل من الأقباط. بحواره اللاهوتي مع الكنائس الأخرى، أوضح العقيدة القبطية للعالم دون تنازل. وقّع إعلاناً مشتركاً مع البابا بولس السادس سنة 1973 م.',
 'نفيه الرئيس أنور السادات إلى دير الأنبا بيشوي سنة 1981 م لمدة ثلاث سنوات. تحديات الهجرة وإنشاء كنائس في بلدان جديدة. النمو السريع للكنيسة.',
 'نشر الكنيسة القبطية في أكثر من 100 دولة، الدروس الأسبوعية للتعليم الديني، إعلان الإيمان المشترك مع الكنيسة الكاثوليكية (1973 م).',
 '', '', '')
ON CONFLICT (papal_number) DO NOTHING;

INSERT INTO patriarchs (id, name_ar, name_en, papal_number, birth_date, death_date, papacy_start, papacy_end, century, short_bio_ar, biography_ar, historical_background_ar, faith_defense_ar, challenges_ar, contributions_ar, image_url, image_source, image_credit)
VALUES
('a0000001-0000-0000-0000-000000000010',
 'البابا تواضروس الثاني', 'Pope Tawadros II', 118,
 '4 نوفمبر 1952 م', '—', '18 نوفمبر 2012 م', '—', 21,
 'البابا المئة والثامن عشر والحالي، يقود الكنيسة القبطية في عصر جديد من الحوار المسكوني والانتشار العالمي.',
 'وُلد وجيه صبحي باقي سليمان في منيا الجبن بطنطا في 4 نوفمبر 1952 م. تخرّج من كلية الصيدلة بجامعة الإسكندرية سنة 1975 م. رُسّم كاهناً باسم ثيؤذور سنة 1986 م. أسقفاً للبحيرة سنة 1997 م. اختير البابا رقم 118 في 4 نوفمبر 2012 م. وقّع إعلاناً مشتركاً مع البابا فرنسيس سنة 2023 م يعترف بالمعمودية المتبادلة. اهتم ببناء كاتدرائية ميلاد المسيح في العاصمة الإدارية الجديدة.',
 'تأتي قيادة البابا تواضروس الثاني في ظل التحديات المعاصرة: انتشار الإعلام والإنترنت، هجرة الأقباط المتزايدة، تغيرات سياسية واجتماعية كبيرة في مصر والشرق الأوسط.',
 'يحفظ البابا تواضروس الثاني الإيمان بالتواصل المسكوني المبني على فهم عميق للعقيدة. إعلان المعمدة المتبادلة مع الكنيسة الكاثوليكية سنة 2023 م خطوة تاريخية. بناء كاتدرائية العاصمة الإدارية رمز لثبات الكنيسة القبطية في مصر.',
 'تحديات الإرهاب والاضطهاد في بعض المناطق. هجرة الأقباط وزيادة الانتشار. ضغوط سياسية واقتصادية. إدارة كنيسة عالمية في أكثر من 100 دولة.',
 'إعلان المعمدة المتبادلة مع الكنيسة الكاثوليكية (2023 م)، بناء كاتدرائية ميلاد المسيح بالعاصمة الإدارية، تطوير الإعلام القبطي، توسيع الحوار المسكوني.',
 '', '', '')
ON CONFLICT (papal_number) DO NOTHING;
